def flush_batch_with_retry(self, sink_fn, batch_size: int = 512, max_retries: int = 3) -> int:
        batch = []
        with self._lock:
            while self._queue and len(batch) < batch_size:
                batch.append(self._queue.popleft())
        if not batch:
            return 0
        for attempt in range(max_retries):
            try:
                sink_fn(batch)
                return len(batch)
            except OSError:
                if attempt == max_retries - 1:
                    # Re-queue or drop explicitly; never block primary ring
                    self.dropped_count += len(batch)
                    return 0
                time.sleep((0.05 * (2 ** attempt)) + random.uniform(0, 0.02))
        return 0
